import { asc, inArray, isNull, sql } from "drizzle-orm";
import { db } from "../db/client.js";
import { dictionaryEntries, dictionaryExampleSentences } from "../db/schema.js";
import { normalizeTerm } from "../lib/normalize.js";

export type DictionaryEntry = typeof dictionaryEntries.$inferSelect;

/**
 * Creates missing dictionary entries. Only a meaning generated by AI may be passed as
 * `aiMeaningPt`; a user's own meaning stays private. It is stored only when the entry has none
 * yet, so the first AI meaning for a term is the one everyone reuses.
 */
export async function ensureEntries(items: { term: string; aiMeaningPt?: string }[]) {
  const unique = new Map(items.map((item) => [normalizeTerm(item.term), item]));
  if (unique.size === 0) return;
  await db
    .insert(dictionaryEntries)
    .values(
      [...unique.entries()].map(([normalizedTerm, item]) => ({
        normalizedTerm,
        term: item.term.trim().replace(/\s+/g, " "),
        meaningPt: item.aiMeaningPt?.trim() || null,
      })),
    )
    .onConflictDoUpdate({
      target: dictionaryEntries.normalizedTerm,
      set: { meaningPt: sql`coalesce(${dictionaryEntries.meaningPt}, excluded.meaning_pt)` },
      setWhere: isNull(dictionaryEntries.meaningPt),
    });
}

export async function getEntries(normalizedTerms: string[]) {
  const rows = normalizedTerms.length
    ? await db
        .select()
        .from(dictionaryEntries)
        .where(inArray(dictionaryEntries.normalizedTerm, normalizedTerms))
    : [];
  return new Map(rows.map((row) => [row.normalizedTerm, row]));
}

/** Example sentences per term, oldest first. */
export async function getExampleSentences(normalizedTerms: string[]) {
  const rows = normalizedTerms.length
    ? await db
        .select()
        .from(dictionaryExampleSentences)
        .where(inArray(dictionaryExampleSentences.normalizedTerm, normalizedTerms))
        .orderBy(asc(dictionaryExampleSentences.id))
    : [];
  const map = new Map<string, string[]>();
  for (const row of rows) {
    map.set(row.normalizedTerm, [...(map.get(row.normalizedTerm) ?? []), row.sentence]);
  }
  return map;
}
